/* CTS seal — places the seminary emblem on every certificate/diploma (screen + print).
   Loaded by all course certificates and the Associate of Ministry degree certificate.
   The catalog's certificates use several different templates, so this locates the
   diploma box, then either fills its seal slot or sits above its header line. Idempotent.
   Print sizing is kept modest so it never breaks the single-page certificate layout. */
(function () {
  "use strict";
  var SEAL = "data:image/png;base64,";

  function emblem() {
    var i = document.createElement("img");
    i.className = "cts-emblem";
    i.src = SEAL;
    i.setAttribute("alt", "Chapala Theological Seminary seal");
    return i;
  }

  function diploma() {
    var sels = [".certificate", "#certificate", "#cert-wrap", ".cert-wrap",
                "#cert", ".cert-outer", ".diploma", "#diploma", "#certCard",
                ".cert-frame", ".cert"];
    for (var i = 0; i < sels.length; i++) {
      var el = document.querySelector(sels[i]);
      if (el) return el;
    }
    return document.body;
  }

  function inject() {
    if (document.querySelector(".cts-emblem")) return;

    var st = document.createElement("style");
    st.textContent =
      ".cts-emblem{display:block;margin:0 auto 6px;height:96px;width:auto;}" +
      ".cert-seal .cts-emblem,.seal .cts-emblem{margin:0 auto 2px;height:104px;}" +
      "@media print{.cts-emblem{height:84px;margin:0 auto 4px;" +
      "-webkit-print-color-adjust:exact;print-color-adjust:exact;}}";
    document.head.appendChild(st);

    var box = diploma();

    // 1) Seal slot present (standard + Radical templates): the emblem IS the seal.
    var slot = box.querySelector(".cert-seal, .seal") ||
               document.querySelector(".cert-seal, .seal");
    if (slot) { slot.innerHTML = ""; slot.appendChild(emblem()); return; }

    // 2) Otherwise sit just above the diploma's header line.
    var anchors = [".crest", ".cert-school", ".cert-header", ".cert-head", "h1"];
    for (var i = 0; i < anchors.length; i++) {
      var a = box.querySelector(anchors[i]);
      if (a && a.parentNode) { a.parentNode.insertBefore(emblem(), a); return; }
    }
    // 3) Last resort: top of the diploma box.
    box.insertBefore(emblem(), box.firstChild);
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", inject);
  else inject();
})();
